<template>
  <div class="page-cfo-exp">
    <header class="page-header">
      <div><h1 class="page-title">{{ form?.card?.title || `ЦФО ${form?.config?.code || ''}` }}</h1>
        <p class="page-subtitle">{{ form?.total ?? 0 }} строк · план {{ planYear }} · {{ form?.config?.country || '—' }}
          <span v-if="form?.read_only" class="lock-note"><Icon name="lucide:lock" /> только просмотр</span></p></div>
      <div class="page-actions"><NuxtLink :to="`/plans/cfo-exp-registry/${cardId}`" class="btn btn-ghost">Реестры</NuxtLink>
        <button class="btn btn-sm btn-ghost" :disabled="loading" @click="check">Проверить</button>
        <button class="btn btn-sm btn-ghost" :disabled="form?.read_only" @click="importInput?.click()">Импорт</button>
        <input ref="importInput" type="file" accept=".xlsx" class="hidden-file" @change="onImport" />
        <button class="btn btn-sm btn-ghost" @click="download">Экспорт</button>
        <button class="btn btn-sm btn-primary" :disabled="!editable || !dirty || saving" @click="save">Сохранить</button></div>
    </header>
    <p v-if="form?.source_error" class="banner banner-warn">Источник: {{ form.source_error }}</p>
    <p v-if="error" class="banner banner-neg">{{ error }}</p><p v-if="note" class="banner banner-pos">{{ note }}</p>
    <div v-if="report?.issues.length" class="card issues"><span class="card-title">Проверка</span><ul><li v-for="(i,n) in report.issues" :key="n"><b>{{ i.code }}</b> {{ i.message }}</li></ul></div>
    <section class="card tabs"><button v-for="t in tabs" :key="t.key" class="seg" :class="{active:tab===t.key}" @click="tab=t.key">{{ t.label }}</button></section>
    <section v-if="tab==='info'" class="card info"><h2>ИНФО</h2><p>Факт и стратегия показываются по данным источника. Если источник продаж или курс не переданы, значение отображается как «—».</p>
      <dl><dt>Факт продаж</dt><dd>—</dd><dt>Стратегия</dt><dd>—</dd><dt>Курс</dt><dd>{{ form?.fx_rate ?? '—' }}</dd></dl></section>
    <section v-else-if="tab==='byn'" class="card info"><h2>Результат ввода в BYN</h2><p>Расчёт доступен после публикации источника курса и исходных данных.</p><strong>—</strong></section>
    <section v-else class="card grid-card">
      <div class="filters"><input v-model="filter.search" class="input" placeholder="Поиск по ЦФО, статье, коду" @keydown.enter="reload" />
        <input v-model="filter.group_pl" class="input" placeholder="Группа PL" @keydown.enter="reload" /><input v-model="filter.expense" class="input" placeholder="Статья" @keydown.enter="reload" />
        <input v-model="filter.code_pl" class="input" placeholder="Код PL" inputmode="numeric" @keydown.enter="reload" /><input v-model="filter.legal_entity" class="input" placeholder="ЮЛ" @keydown.enter="reload" /><input v-model="filter.country" class="input" placeholder="Страна ЮЛ" @keydown.enter="reload" />
        <button class="btn btn-sm btn-ghost" @click="reload">Применить</button><button class="btn btn-sm btn-ghost" @click="reset">Сбросить</button></div>
      <div class="history"><span>История:</span><label v-for="y in factYears" :key="y"><input type="checkbox" v-model="history[y]" /> {{ y }}</label></div>
      <div ref="grid" class="grid-scroll" @paste="nav.onPaste"><table class="data-table compact"><thead><tr><th v-for="c in attrs" :key="c.key" @click="sortBy(c.key)">{{c.label}}{{sortMark(c.key)}}</th><th v-for="m in 12" :key="m" class="col-num" @click="sortBy(`m${m}`)">{{m}}<small>{{sortMark(`m${m}`)}}</small></th><template v-for="hy in visibleHistoryYears" :key="`h-${hy}`"><th v-for="m in 12" :key="`${hy}-${m}`" class="col-num hist">{{hy}}/{{m}}</th></template><th>Итого</th><th>Действия</th></tr></thead>
        <tbody><template v-for="g in groups" :key="g"><tr class="grp" @click="collapsed[g]=!collapsed[g]"><td :colspan="attrs.length+14+visibleHistoryYears.length*12">{{ collapsed[g]?'▶':'▼' }} {{g}} <small>({{groupRows(g).length}})</small></td></tr>
          <tr v-for="(row,ri) in groupRows(g)" v-show="!collapsed[g]" :key="row.id"><td>{{row.code_cfo}}{{row.cfo ? ` · ${row.cfo}` : ''}}</td><td>{{row.code_pl}}</td><td>{{row.expense}}</td><td>{{row.legal_entity || '—'}}</td>
            <td v-for="m in 12" :key="m" class="col-num"><input class="cell-input" :data-grid-cell="`${flatIndex(row)}:${m-1}`" :value="text(row,m)" :disabled="!editable" inputmode="decimal" @focus="nav.onFocusCell(flatIndex(row),m-1)" @keydown="nav.onKeydown($event,flatIndex(row),m-1)" @input="draft(row,m,($event.target as HTMLInputElement).value)" /></td>
            <template v-for="hy in visibleHistoryYears" :key="hy"><td v-for="m in 12" :key="`${hy}-${m}`" class="col-num hist">{{ historyText(row,hy,m) }}</td></template><td class="col-num">{{ money(total(row)) }}</td><td><button class="btn btn-xs btn-ghost" :disabled="!editable" @click="bulk(row,'year')">год</button><button class="btn btn-xs btn-ghost" :disabled="!editable" @click="bulk(row,'to_end')">до конца</button><button class="btn btn-xs btn-ghost" :disabled="!editable" @click="bulk(row,'clear')">очистить</button><input class="comment" :value="row.comment" :disabled="!editable" placeholder="Комментарий" @change="comment(row,($event.target as HTMLInputElement).value)" /></td></tr>
        </template></tbody></table></div>
      <div v-if="hasMore" class="grid-more"><button class="btn btn-sm btn-ghost" @click="loadMore">Показать ещё · {{ rows.length }} / {{ form?.total }}</button></div>
    </section>
    <section v-if="importReport" class="card"><h2>Импорт — предпросмотр</h2><p>Изменений: {{ importReport.changes.length }}, ошибок: {{ importReport.issues.length }}</p><ul><li v-for="(i,n) in importReport.issues" :key="n">{{ typeof i==='string'?i:i.message }}</li></ul><button class="btn btn-primary" :disabled="!editable" @click="applyImport">Применить импорт</button></section>
  </div>
</template>
<script setup lang="ts">
import { money } from '~/utils/format'; import { apiError } from '~/utils/apiError'; import { useGridNav } from '~/composables/useGridNav';
import { useCfoExpense, type CfoExpenseForm, type CfoExpenseRow, type CfoExpenseCell, type CfoExpenseImport, type CfoExpenseIssue } from '~/composables/useCfoExpense';
const route=useRoute(); const cardId=Number(route.params.cardId); const api=useCfoExpense(); const form=ref<CfoExpenseForm|null>(null); const rows=ref<CfoExpenseRow[]>([]); const loading=ref(true); const saving=ref(false); const error=ref(''); const note=ref(''); const tab=ref('input'); const report=ref<{issues:CfoExpenseIssue[]}|null>(null); const importReport=ref<CfoExpenseImport|null>(null); const importFileRef=ref<File|null>(null); const importInput=ref<HTMLInputElement|null>(null); const drafts=ref<Map<string,number|null>>(new Map());
const filter=reactive({search:'',group_pl:'',expense:'',code_pl:'',legal_entity:'',country:''}); const sort=ref<{key:string,desc:boolean}|null>(null); const collapsed=reactive<Record<string,boolean>>({}); const history=reactive<Record<number,boolean>>({});
const tabs=[{key:'input',label:'Ввод'},{key:'info',label:'ИНФО'},{key:'byn',label:'Результат ввода в BYN'}]; const attrs=[{key:'code_cfo',label:'ЦФО'},{key:'code_pl',label:'Код PL'},{key:'expense',label:'Статья'},{key:'legal_entity',label:'ЮЛ'}];
const planYear=computed(()=>form.value?.config.plan_year||new Date().getFullYear()); const factYears=computed(()=>form.value?.config.fact_years||[]); const historyYears=computed(()=>Array.from(new Set([...factYears.value,...(form.value?.config.comparison_years||[])])).sort()); const visibleHistoryYears=computed(()=>historyYears.value.filter(y=>history[y])); const editable=computed(()=>!!form.value&&!form.value.read_only); const dirty=computed(()=>drafts.value.size>0); const hasMore=computed(()=>!!form.value&&rows.value.length<form.value.total);
const key=(r:CfoExpenseRow,m:number)=>`${r.id}:${m}`; const saved=(r:CfoExpenseRow,m:number)=>{const plan=r.values.find(v=>v.scenario==='plan'&&v.year===planYear.value&&v.month===m);if(plan)return plan.amount;return r.values.find(v=>v.scenario===form.value?.config.plan_scenario&&v.year===planYear.value&&v.month===m)?.amount??null}; const value=(r:CfoExpenseRow,m:number)=>drafts.value.has(key(r,m))?drafts.value.get(key(r,m))??null:saved(r,m); const text=(r:CfoExpenseRow,m:number)=>{const v=value(r,m);return v===null?'':String(v)};
const flatRows=computed(()=>rows.value.filter(r=>!collapsed[r.group_pl])); const flatIndex=(r:CfoExpenseRow)=>flatRows.value.findIndex(x=>x.id===r.id); const nav=useGridNav({rows:()=>flatRows.value.length,cols:()=>12, onPaste:(a,m)=>m.forEach((line,i)=>line.forEach((raw,j)=>{const r=flatRows.value[a.row+i];if(r&&a.col+j<12)draft(r,a.col+j+1,raw)}))});
const grid=nav.container;
const groups=computed(()=>{const s=[...new Set(rows.value.map(r=>r.group_pl||'Без группы'))];return s}); const historyText=(r:CfoExpenseRow,y:number,m:number)=>{const scenario=(form.value?.config.comparison_years||[]).includes(y)?form.value?.config.comparison_scenario:form.value?.config.fact_scenario;const v=r.values.find(x=>x.year===y&&x.month===m&&x.scenario===scenario)?.amount;return v===null||v===undefined?'—':money(v)}; const groupRows=(g:string)=>rows.value.filter(r=>(r.group_pl||'Без группы')===g); const total=(r:CfoExpenseRow)=>Array.from({length:12},(_,i)=>value(r,i+1)||0).reduce((a,b)=>a+b,0); const sortMark=(k:string)=>sort.value?.key===k?(sort.value.desc?' ↓':' ↑'):'';
const sortBy=(k:string)=>{sort.value=sort.value?.key!==k?{key:k,desc:false}:!sort.value.desc?{key:k,desc:true}:null;reload()}; const query=(offset:number)=>({search:[filter.search,filter.expense].filter(Boolean).join(' '),group_pl:filter.group_pl||undefined,code_pl:filter.code_pl?Number(filter.code_pl):undefined,legal_entity:filter.legal_entity||undefined,country_company:filter.country||undefined,offset,limit:500,sort:sort.value?.key,dir:sort.value?.desc?'desc':undefined});
function draft(r:CfoExpenseRow,m:number,raw:string){const v=raw.trim()===''?null:Number(raw.replace(/\s/g,'').replace(',','.'));if(raw.trim()!==''&&!Number.isFinite(v))return;const n=new Map(drafts.value);n.set(key(r,m),v);drafts.value=n} function comment(r:CfoExpenseRow,v:string){r.comment=v;const n=new Map(drafts.value);n.set(`comment:${r.id}`,null);drafts.value=n}
async function reload(){loading.value=true;try{const f=await api.form(cardId,query(0));form.value=f;rows.value=f.rows;const years=[...new Set([...(f.config.fact_years||[]),...(f.config.comparison_years||[])])];years.forEach(y=>{if(history[y]===undefined)history[y]=false});if(import.meta.client){const raw=localStorage.getItem('cfo-exp-layout:'+f.config.code+':'+f.config.country);if(raw)Object.assign(history,JSON.parse(raw))}}catch(e){error.value=apiError(e,'Не удалось загрузить форму')}finally{loading.value=false}}
async function loadMore(){if(!form.value)return;const f=await api.form(cardId,query(rows.value.length));rows.value.push(...f.rows)}
async function save(){saving.value=true;try{const cells:CfoExpenseCell[]=[];const comments:any[]=[];drafts.value.forEach((v,k)=>{if(k.startsWith('comment:'))return;const [id,m]=k.split(':').map(Number);const r=rows.value.find(x=>x.id===id);if(r)cells.push({code_cfo:r.code_cfo,code_pl:r.code_pl,legal_entity:r.legal_entity,month:m,amount:v})});rows.value.forEach(r=>{if(drafts.value.has(`comment:${r.id}`))comments.push({code_cfo:r.code_cfo,code_pl:r.code_pl,legal_entity:r.legal_entity,comment:r.comment||''})});await api.save(cardId,cells,comments);drafts.value=new Map();note.value='Сохранено';await reload()}catch(e){error.value=apiError(e,'Не удалось сохранить')}finally{saving.value=false}}
async function bulk(r:CfoExpenseRow,op:'year'|'to_end'|'clear'){const m=nav.active.value?.row===flatIndex(r)?(nav.active.value.col+1):1;try{await api.bulk(cardId,{code_cfo:r.code_cfo,code_pl:r.code_pl,legal_entity:r.legal_entity,month:m,amount:op==='clear'?null:value(r,m)},op);await reload()}catch(e){error.value=apiError(e,'Массовая операция не выполнена')}}
async function check(){try{report.value=await api.validate(cardId)}catch(e){error.value=apiError(e,'Проверка не выполнена')}} async function download(){await api.export(cardId,query(0))} function reset(){Object.assign(filter,{search:'',group_pl:'',expense:'',code_pl:'',legal_entity:'',country:''});reload()}
async function onImport(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;importFileRef.value=f;importReport.value=await api.import(cardId,f,true)} async function applyImport(){if(!importFileRef.value)return;await api.import(cardId,importFileRef.value,false);importReport.value=null;await reload()}
onMounted(()=>reload()); watch(history,()=>{if(import.meta.client&&form.value)localStorage.setItem('cfo-exp-layout:'+form.value.config.code+':'+form.value.config.country,JSON.stringify(history))},{deep:true});
</script>
<style scoped>.page-cfo-exp{display:flex;flex-direction:column;gap:var(--sp-4)}.tabs,.filters,.history{display:flex;gap:var(--sp-2);align-items:center;flex-wrap:wrap}.filters{padding:var(--sp-3)}.filters .input{min-width:125px}.grid-scroll{overflow:auto;max-height:70vh}.data-table{min-width:1450px}.data-table th{cursor:pointer;white-space:nowrap}.cell-input{width:82px}.comment{width:130px}.grp{cursor:pointer;background:var(--bg-surface-2)}.info{padding:var(--sp-5)}.issues{padding:var(--sp-3)}.hidden-file{display:none}</style>
